import {readFileSync} from 'node:fs';
import {expect, type Page, test} from '@playwright/test';
import {
  bundledFamilies,
  COVERED_CHARACTERS,
  foreignFontUses,
} from '../../../tools/e2e/bundled-fonts.mjs';
import {screenCheck} from './checks/screen-check.js';

/**
 * The bundled-font check checks itself on pages that load the real bundled faces: it passes text
 * a face has glyphs for, and fails text it lacks (the check mark of a step list, which the body
 * face does not have and the mono face does), whether the text is in the page or generated by CSS.
 */

const UI = new URL('../../../libs/ui/src/', import.meta.url);
const ORIGIN = 'https://app.test';

/** Opens `body` on a page that serves the UI library's `fonts.css` and its font files. */
async function show(page: Page, body: string): Promise<void> {
  await page.route(`${ORIGIN}/**`, route => {
    const path = new URL(route.request().url()).pathname;
    if (path === '/') {
      return route.fulfill({
        contentType: 'text/html',
        body: `<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="/fonts.css"><body>${body}</body>`,
      });
    }
    const type = path.endsWith('.css') ? 'text/css' : 'font/woff2';
    return route.fulfill({contentType: type, body: readFileSync(new URL(`.${path}`, UI))});
  });
  await page.goto(`${ORIGIN}/`);
  await page.evaluate(async () => {
    await Promise.all(
      ['400 14px "Schibsted Grotesk"', '400 14px "JetBrains Mono"'].map(font =>
        document.fonts.load(font, '✓· 3×abc'),
      ),
    );
  });
}

const SANS = "font-family: 'Schibsted Grotesk'";
const MONO = "font-family: 'JetBrains Mono'";

test('the bundled families are the ones fonts.css declares', () => {
  expect([...bundledFamilies()].sort()).toEqual(['JetBrains Mono', 'Schibsted Grotesk']);
  expect([...bundledFamilies('@font-face { font-family: "A B"; }')]).toEqual(['A B']);
});

test('text the face has glyphs for passes, in the page and in generated content', async ({
  page,
}) => {
  await show(
    page,
    `<style>.mark::before { content: "✓"; ${MONO} }</style>
     <p style="${SANS}">Done · 3× faster … “quoted”</p>
     <p style="${MONO}">✓ ● ✕ ○ ═ █</p>
     <p class="mark" style="${SANS}">ready</p>`,
  );
  expect(await foreignFontUses(page)).toEqual([]);
  expect(await screenCheck(page, ['bundled-font'])).toEqual([]);
});

test('every character the check skips is in both bundled faces', async ({page}) => {
  // The check asks the browser only about text with a character outside this set.
  await show(
    page,
    `<p style="${SANS}">${COVERED_CHARACTERS}</p><p style="${MONO}">${COVERED_CHARACTERS}</p>`,
  );
  expect(await foreignFontUses(page)).toEqual([]);
});

test('a symbol the body face lacks fails, naming the element and the font that drew it', async ({
  page,
}) => {
  await show(page, `<p id="done" style="${SANS}">Done ✓</p><p style="${SANS}">plain</p>`);
  const violations = await screenCheck(page, ['bundled-font']);
  expect(violations.map(each => each.where)).toEqual(['p#done']);
  expect(violations[0]?.check).toBe('bundled-font');
  expect(violations[0]?.message).toMatch(/"Done ✓" is drawn by .+, not a bundled font/);
});

test('a symbol the body face lacks fails when CSS generates it', async ({page}) => {
  await show(
    page,
    `<style>.mark::before { content: "✕"; }</style><p class="mark" style="${SANS}">failed</p>`,
  );
  const violations = await screenCheck(page, ['bundled-font']);
  expect(violations.map(each => each.where)).toEqual(['p.mark::before']);
});

test('a symbol typed into a field or chosen in a menu fails too', async ({page}) => {
  await show(
    page,
    `<input aria-label="a" style="${SANS}" value="✓"/>
     <input aria-label="b" style="${SANS}" placeholder="✓"/>
     <select aria-label="c" style="${SANS}"><option>✓</option></select>
     <textarea aria-label="d" style="${SANS}">✓</textarea>`,
  );
  const violations = await screenCheck(page, ['bundled-font']);
  expect(violations.map(each => each.where.split(' > ')[0])).toEqual([
    'input',
    'input',
    'select',
    'textarea',
  ]);
});
